import{B as uo,P as jl,W as zl,_ as R,c as Gl,h as Os,i as Bl,n as $w,r as AE,u as Lh,w as Xw}from"./main-CZ54HXHY.js";var h=[{slug:`tiky`,name:`Tiky`,status:`recovering`,featured:!0,summary:`Tiky tenía apenas 3 meses cuando sufrió una fractura expuesta en una de sus patas traseras. Tras varios días de internación y estabilización, pudo ser operada: la amputación salió muy bien y hoy continúa recuperándose.`,coverImage:{src:`/images/cases/tiky/cover.avif`,alt:`Tiky durante su recuperación`,objectPosition:`50% 40%`},gallery:[{src:`/images/cases/tiky/01.avif`,alt:`Tiky durante su internación veterinaria`},{src:`/images/cases/tiky/02.avif`,alt:`Tiky con sus patitas vendadas durante el tratamiento`},{src:`/images/cases/tiky/04.avif`,alt:`Tiky después de la cirugía de amputación`},{src:`/images/cases/tiky/05.avif`,alt:`Tiky durante su recuperación luego de recibir el alta`},{src:`/images/cases/tiky/06.avif`,alt:`Tiky durante su recuperación luego de recibir el alta`}],story:[`Tiky tenía apenas 3 meses. Nació de una gata feral en el Parque Industrial y hasta ese momento nunca había conocido el calor de un hogar: su vida había sido sobrevivir.`,`A fines de julio ocurrió un accidente mientras estaba refugiada debajo de un pallet. Una máquina elevadora enganchó una de sus patitas traseras y se la destrozó. Tiky permaneció muchas horas sin recibir atención, con una fractura expuesta, dolor, tierra y una infección que avanzaba sobre su pequeño cuerpo.`,`Finalmente, uno de los trabajadores del lugar la vio y decidió actuar. El 28 de julio Tiky pudo ser rescatada e internada. Comenzó a recibir antibióticos, analgésicos y los cuidados necesarios para estabilizarla. Desde el comienzo, los veterinarios sabían que, cuando su estado lo permitiera, sería necesario amputar la patita lesionada para poder salvarle la vida.`,`Durante los días siguientes continuó internada y, aunque anímicamente se encontraba muy bien, algunos valores de sus análisis generaban preocupación. Los estudios de PCR para VIF y VILEF dieron negativos, una muy buena noticia, pero se comenzó a evaluar realizar la cirugía cuanto antes para evitar que su cuadro empeorara.`,`El 3 de agosto, durante un control, descubrieron además una herida en la otra patita que estaba supurando. Tiky terminó con ambas patitas vendadas. Aun así, seguía adelante: había sobrevivido al dolor, a la infección, al frío y al hambre, y ya estaba recibiendo cuidados y cariño.`,`El 5 de agosto finalmente se realizó la cirugía de amputación de su patita trasera izquierda. La operación salió más que bien y Tiky pudo recibir el alta. Quedó bajo el cuidado de Facu y Bel, quienes continuaron acompañándola durante su recuperación.`,`Después de la cirugía todavía necesitaba controles y medicación durante varios días, hasta que pudieran retirarle los puntos. Su otra patita, que también había resultado lesionada, debía continuar cicatrizando.`,`El caso de Tiky se sumó a otros rescates que durante el año requirieron cirugías de amputación, entre ellos Fénix (Gatoman) y Patán. En esos casos también hubo fracturas expuestas e infecciones asociadas al tiempo transcurrido sin atención inmediata.`,`Su historia muestra por qué muchos rescates no pueden esperar. Además de las urgencias veterinarias, los tratamientos, estudios, internaciones y cirugías, los tránsitos también generan gastos cotidianos de alimentación y piedritas. Cada ayuda y cada difusión permiten que estos animales tengan una oportunidad.`],currentNeeds:[{title:`Controles veterinarios`,description:`Después de la cirugía necesita continuar con controles durante su recuperación y hasta que los profesionales indiquen que pueden retirarle los puntos.`},{title:`Medicación`,description:`Debe continuar con la medicación indicada por los profesionales durante los días posteriores a la cirugía.`},{title:`Cicatrización de sus heridas`,description:`Además de la amputación, su otra patita también estaba lesionada y necesita continuar cicatrizando correctamente.`}],updates:[{date:`2026-08-05`,title:`La cirugía salió más que bien`,paragraphs:[`Se realizó la cirugía de amputación de la patita trasera izquierda de Tiky y, como se esperaba, la operación salió muy bien.`,`Tiky recibió el alta y quedó bajo el cuidado de Facu y Bel, quienes la acompañan con mucho amor, responsabilidad y compromiso.`,`Durante los días siguientes debe continuar con controles y medicación hasta que puedan retirarle los puntos. Su otra patita, que también estaba lesionada, todavía necesita terminar de cicatrizar.`,`La publicación señala que Tiky fue el tercer animal rescatado del año que necesitó una cirugía de amputación, junto con Fénix (Gatoman) y Patán. En los tres casos hubo fractura expuesta e infección luego de haber pasado tiempo sin atención inmediata.`,`Además de los gastos veterinarios, la rescatista recordó que los tránsitos generan gastos de alimentación y piedritas, incluso en animales que muchas veces no llegan a aparecer en publicaciones.`,`Ese día informó que la deuda veterinaria general ya había superado los $1.500.000 y que todavía faltaba conocer el monto exacto actualizado, pese a las entregas que había logrado realizar.`]},{date:`2026-08-03`,title:`Descubrieron una lesión en la otra patita`,paragraphs:[`Durante el control matutino encontraron una herida en la otra patita de Tiky que estaba supurando un poco. Como consecuencia, quedó con ambas patitas vendadas.`,`A pesar de todo lo que había atravesado —dolor, infección, frío y hambre—, Tiky seguía adelante y ya estaba recibiendo muchos cuidados y cariño.`,`Si su evolución continuaba bien, la cirugía de amputación estaba prevista para realizarse durante esa semana.`,`La rescatista contó que ese día realizó una entrega de $240.000 en la veterinaria. Después de esa entrega, informó un saldo general pendiente de $1.416.800, al que todavía debían sumarse la cirugía y los controles de Tiky.`]},{date:`2026-07-31`,title:`Buen ánimo y nuevos estudios`,paragraphs:[`Tiky se encontraba anímicamente muy bien y se mostraba relajada incluso mientras recibía la medicación.`,`Sin embargo, algunos valores de los análisis no estaban bien, por lo que los profesionales estaban evaluando realizar la cirugía cuanto antes para evitar que su cuadro empeorara.`,`Los análisis de PCR para VIF y VILEF dieron negativos, lo que representó una muy buena noticia dentro de su evolución.`,`El día anterior la rescatista había podido realizar una entrega de $250.000 en la veterinaria. En esta actualización informó que todavía quedaban $1.352.800 de deuda veterinaria general, antes de sumar los controles y la cirugía de amputación de Tiky.`,`También contó que todavía tenía números de una rifa a la venta como otra forma de reunir fondos para seguir afrontando los gastos.`]},{date:`2026-07-28`,title:`Tiky necesitaba una oportunidad para vivir`,paragraphs:[`Tiky tenía apenas 3 meses y había nacido de una gata feral en el Parque Industrial. Nunca había conocido el calor de un hogar y su vida, hasta entonces, había sido sobrevivir.`,`Mientras estaba refugiada debajo de un pallet, una máquina elevadora enganchó su patita y se la destrozó. Permaneció muchas horas sin poder recibir ayuda.`,`Cuando finalmente uno de los trabajadores del lugar la vio y decidió actuar, Tiky tenía una fractura expuesta, mucho dolor, tierra en la herida y una infección que avanzaba sobre su cuerpo.`,`Fue internada y comenzó a recibir antibióticos, analgésicos y todos los cuidados necesarios para estabilizarla. La indicación era que, cuando su estado lo permitiera, deberían amputarle la patita para salvarle la vida.`,`En ese momento la deuda veterinaria general ascendía a $1.454.206, sin incluir todavía la internación de Tiky ni los gastos que vendrían después.`,`Además de la colaboración económica para los gastos veterinarios, en esa publicación también se pidió alimento de buena calidad y piedritas para acompañar los tránsitos.`]}],updatedAt:`2026-08-05`,seoDescription:`Conocé la historia de Tiky, rescatada con una fractura expuesta a los 3 meses, y su recuperación después de una cirugía de amputación.`},{slug:`caso-pendiente-1`,name:`[Nombre del animal]`,status:`needs-help`,featured:!0,summary:`[Resumen breve proporcionado por la rescatista]`,coverImage:{src:`/images/placeholders/case-placeholder.svg`,alt:`Foto pendiente del caso`},gallery:[],story:[`[Historia proporcionada por la rescatista]`],currentNeeds:[],updates:[],updatedAt:null},{slug:`caso-pendiente-2`,name:`[Nombre del animal]`,status:`recovering`,featured:!0,summary:`[Resumen breve proporcionado por la rescatista]`,coverImage:{src:`/images/placeholders/case-placeholder.svg`,alt:`Foto pendiente del caso`},gallery:[],story:[`[Historia proporcionada por la rescatista]`],currentNeeds:[],updates:[],updatedAt:null},{slug:`caso-pendiente-3`,name:`[Nombre del animal]`,status:`treatment`,featured:!0,summary:`[Resumen breve proporcionado por la rescatista]`,coverImage:{src:`/images/placeholders/case-placeholder.svg`,alt:`Foto pendiente del caso`},gallery:[],story:[`[Historia proporcionada por la rescatista]`],currentNeeds:[],updates:[],updatedAt:null}];var C=class s{cases=h;getBySlug(e){return this.cases.find(a=>a.slug===e)}getFeatured(){return this.cases.filter(e=>e.featured)}getByStatus(e){return e===`all`?this.cases:this.cases.filter(a=>a.status===e)}static ɵfac=function(a){return new(a||s)};static ɵprov=R({token:s,factory:s.ɵfac,providedIn:`root`})};var E={"needs-help":{label:`Necesita ayuda`,tone:`danger`},treatment:{label:`En tratamiento`,tone:`neutral`},recovering:{label:`En recuperación`,tone:`success`},closed:{label:`Caso cerrado`,tone:`neutral`},memorial:{label:`En memoria`,tone:`muted`}};var q=class s{status=Os.required();meta=uo(()=>E[this.status()]);classes=uo(()=>{let e=`inline-flex items-center gap-2 rounded-full border px-3 py-1 text-xs font-bold`;switch(this.meta().tone){case`danger`:return`${e} border-[var(--color-accent-soft)] bg-[var(--color-danger-bg)] text-[var(--color-accent-soft)]`;case`success`:return`${e} border-[var(--color-recovering)] bg-[var(--color-recovering-bg)] text-[var(--color-recovering)]`;case`muted`:return`${e} border-[var(--color-border)] bg-white text-[var(--color-text-muted)]`;default:return`${e} border-[var(--color-text-muted)] bg-white text-[var(--color-text)]`}});static ɵfac=function(a){return new(a||s)};static ɵcmp=jl({type:s,selectors:[[`app-status-badge`]],inputs:{status:[1,`status`]},decls:3,vars:3,consts:[[`aria-hidden`,`true`,1,`h-1.5`,`w-1.5`,`rounded-full`,`bg-current`]],template:function(a,t){a&1&&(Bl(0,`span`),Lh(1,`span`,0),Xw(2),zl()),a&2&&($w(t.classes()),AE(2),Gl(` `,t.meta().label,` `))},encapsulation:2})};export{E as n,q as r,C as t};